using System.Collections.Immutable;
using System.Reflection;
using System.Text.Json;
using Aion.Commons.Nio;
using Aion.GameServer.GeoEngine.RetailPath;
using Aion.GameServer.Network.Aion;
using Aion.GameServer.Network.Aion.ServerPackets;
using P = Aion.GameServer.GeoEngine.RetailPath.RetailNpc48MoveDeletePackets;
using M = Aion.GameServer.GeoEngine.RetailPath.RetailNpcManagedMembershipMove;
using O = Aion.GameServer.GeoEngine.RetailPath.RetailNpcManagedMembershipObservation;
using V = Aion.GameServer.GeoEngine.RetailPath.RetailNpcManagedVisibility;

namespace Aion.GameServer.Tests;

public sealed class RetailNpc48MoveDeletePacketsTests
{
    private const string Corpus = "";
    public static IEnumerable<object[]> WireCases()
    {
        using var json = JsonDocument.Parse(Convert.FromBase64String(Corpus));
        foreach (var row in json.RootElement.GetProperty("cases").EnumerateArray())
            yield return new object[] { row.GetProperty("sourceFlags").GetInt32(), row.GetProperty("payload").GetString()! };
    }
    [Theory] [MemberData(nameof(WireCases))]
    public void EveryIncomingFlagClassUsesTheJava48NpcGrammarAndExistingOpcode(int sourceFlags, string expectedHex)
    {
        byte flags = (byte)(sourceFlags & 0xef);
        var goal = (flags & 0xe0) == 0xe0 ? new RetailMainVectorWords(0x40400000,0x40800000,0x40a00000) : default;
        var move = new V.Move(100,0x80000007,new(0x80000000,0x3f800000,0xc0000000),119,flags,goal,0);
        var body = P.CalculateBody(Intent(move));
        Assert.Equal(P.Status.Encoded,body.Status); Assert.Null(body.Failure); Assert.False(body.HostEffectsExecuted);
        Assert.Equal(typeof(SM_MOVE),body.OpcodeOwner); Assert.Equal(Convert.FromHexString(expectedHex),body.Bytes.ToArray());
        var packet = P.SnapshotPacket.FromEncodedBody(body);
        Assert.Equal(55,packet.GetOpCode()); Assert.Equal(body.Bytes.ToArray(),Capture(packet));
    }
    [Theory]
    [InlineData(0x00000000u)] [InlineData(0x80000000u)] [InlineData(0x7fc12345u)] [InlineData(0x7f800000u)]
    [InlineData(0x00000001u)] [InlineData(0xff800000u)]
    public void PacketCopyPreservesEveryRawWordWithoutNumericalNormalization(uint word)
    {
        var body=P.CalculateBody(Intent(new V.Move(1,2,new(word,word,word),0,0xe4,new(word,word,word),0)));
        Assert.Equal(P.Status.Encoded,body.Status);Assert.Equal(31,body.Bytes.Length);
        byte[] raw=body.Bytes.ToArray();
        foreach(int offset in new[]{4,8,12,18,22,26})
            Assert.Equal(word,System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(raw.AsSpan(offset,4)));
        Assert.Equal((byte)0,raw[30]);
    }
    [Fact]
    public void OrdinaryDeleteUsesExisting48OpcodeAndNoneAnimation()
    {
        var body=P.CalculateBody(Intent(new V.Delete(100,0x80000007,0)));
        Assert.Equal(P.Status.Encoded,body.Status);Assert.Equal(typeof(SM_DELETE),body.OpcodeOwner);
        Assert.Equal("0700008000",Convert.ToHexStringLower(body.Bytes.AsSpan()));
        var packet=P.SnapshotPacket.FromEncodedBody(body);Assert.Equal(22,packet.GetOpCode());Assert.Equal(body.Bytes.ToArray(),Capture(packet));
    }
    [Theory] [InlineData(false)] [InlineData(true)]
    public void NoConnectionSkipsUnreachedSpawnOrUnknownDeleteCodec(bool spawn)
    {
        V.Meaning meaning=spawn?new V.Spawn(100,7,[],0):new V.Delete(100,7,255);
        var body=P.CalculateBody(Intent(meaning) with {HasConnection=false});
        Assert.Equal(P.Status.NoConnection,body.Status);Assert.Null(body.OpcodeOwner);Assert.Empty(body.Bytes);
    }
    [Theory] [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)] [InlineData(4)]
    public void InvalidOrUnclosedMeaningProducesNoPacket(int variant)
    {
        V.Meaning meaning=variant switch {
            0=>new V.Move(100,7,default,120,0,default,0),
            1=>new V.Move(100,7,default,0,0x10,default,0),
            2=>new V.Move(100,7,default,0,4,default,3),
            3=>new V.Delete(100,7,1),_=>new V.Spawn(100,7,[],0)};
        var body=P.CalculateBody(Intent(meaning));Assert.Contains(body.Status,new[]{P.Status.InvalidMeaning,P.Status.UnsupportedMeaning});
        Assert.Empty(body.Bytes);Assert.Null(body.OpcodeOwner);Assert.NotNull(body.Failure);
        Assert.Throws<ArgumentException>(()=>P.SnapshotPacket.FromEncodedBody(body));
    }
    [Fact]
    public void FullBatchWithholdsEarlierPacketsWhenConnectedSpawnNeedsItsAdapter()
    {
        var result=RetailNpcManagedVisibilityTests.Complete(ManagedMembershipFixture.Make());
        var batch=P.CalculateCompleted(result.Candidate!);
        Assert.Equal(P.Status.UnsupportedMeaning,batch.Status);Assert.Empty(batch.Deliveries);Assert.NotNull(batch.FailureIndex);
        Assert.True(batch.FailureIndex!.Value>0);Assert.False(batch.HostEffectsExecuted);Assert.False(batch.CanApplyToHost);Assert.False(batch.ActivationReady);
    }
    [Fact]
    public void CompleteMoveDeleteBatchCopiesRecipientLifetimesAndLeavesOriginalOnceLedgerUnconsumed()
    {
        var i=ManagedMembershipFixture.Make();i=ManagedMembershipFixture.UserImage(i,0,u=>O.Replace(u,0x731d,[1]));
        i=i with {Clocks=i.Clocks.Where(c=>c.RecipientId!=100).ToImmutableArray()};
        var result=RetailNpcManagedVisibilityTests.Complete(i);var owner=M.Owner.FromDeclaredInput(i);
        var batch=P.CalculateCompleted(result.Candidate!);Assert.Equal(P.Status.Encoded,batch.Status);Assert.Equal(2,batch.Deliveries.Length);
        Assert.False(owner.Consumed);Assert.Equal(result.Candidate!.Value.SourceSnapshotSha256,batch.SourceSnapshotSha256);
        Assert.Equal(result.Candidate.Value.Operation,batch.Operation);Assert.Equal(result.Candidate.Value.Epoch,batch.Epoch);
        foreach(var delivery in batch.Deliveries)
        {
            var user=Assert.Single(i.Scene.Users,u=>u.Key.ObjectId==delivery.RecipientId);
            Assert.Equal(user.Key.Lifetime,delivery.RecipientLifetime);Assert.Equal(user.ConnectionGeneration,delivery.ConnectionGeneration);
            Assert.Equal(7u,delivery.ObjectId);Assert.Contains(delivery.Packet.GetOpCode(),new[]{22,55});
        }
        Assert.Equal(M.OnceStatus.ComputedFirstApplication,owner.CalculateOnce(result.Candidate).Status);
    }
    [Fact]
    public void PacketSnapshotHasNoMutableCreatureAndRepeatedWritesAreIdentical()
    {
        var body=P.CalculateBody(Intent(new V.Move(100,7,new(0x3f800000,0,0),1,0xe4,new(0x40000000,0,0),0)));
        var packet=P.SnapshotPacket.FromEncodedBody(body);byte[] first=Capture(packet);first[0]=255;
        Assert.Equal(body.Bytes.ToArray(),Capture(packet));Assert.DoesNotContain(typeof(P.SnapshotPacket).GetFields(BindingFlags.NonPublic|BindingFlags.Instance),
            f=>typeof(Aion.GameServer.Model.GameObjects.VisibleObject).IsAssignableFrom(f.FieldType));
    }
    private static V.Intent Intent(V.Meaning value)=>new(value,"recipient-life","connection-generation",true);
    private static byte[] Capture(AionServerPacket packet)
    {
        var buffer=ByteBuffer.Allocate(128).Order(ByteOrder.LITTLE_ENDIAN);packet.SetBuf(buffer);
        typeof(AionServerPacket).GetMethod("WriteImpl",BindingFlags.Instance|BindingFlags.NonPublic,
            new[]{typeof(AionConnection)})!.Invoke(packet,new object?[]{null});
        byte[] bytes=new byte[buffer.Position()];buffer.Flip();buffer.Get(bytes);return bytes;
    }
}
